parameters.jsCode:
const r = $input.all()[0].json.data || $input.all()[0].json;
// Skip if order is no longer delivered (e.g., returned)
if ((r.status || '').toUpperCase() !== 'DELIVERED') {
  return [{ json: { skip: true, reason: `Order status is ${r.status}, not DELIVERED` } }];
}
const productNames = (r.items || []).map(i => i.productName || i.name || 'your purchase').join(', ');
const usageTips = `<ul>${(r.items || []).map(i => `<li><strong>${i.productName || i.name}:</strong> Use as directed. For best results, follow the recommended dosage & timing.</li>`).join('') || '<li>For product usage tips, please visit our knowledge base.</li>'}</ul>`;
const reviewUrl = `https://app.dayjoy.in/orders/${r.id || r.orderNumber}/review`;
const html = `
<!doctype html><html><body style="font-family:Arial,Helvetica,sans-serif;color:#1f2937;background:#fff7ed;margin:0;padding:0;">
  <div style="max-width:600px;margin:0 auto;padding:32px;">
    <h1 style="color:#ea580c;">How's ${productNames} working for you?</h1>
    <p>Hi ${r.customer?.firstName || 'Customer'},</p>
    <p>We hope you're enjoying your recent purchase from Dayjoy. Your feedback helps us improve and helps other customers make informed decisions.</p>
    <h2 style="color:#9a3412;">Quick Usage Tips</h2>
    ${usageTips}
    <h2 style="color:#9a3412;">Share Your Experience</h2>
    <p>Take 60 seconds to leave a review — it truly helps.</p>
    <p><a href="${reviewUrl}" style="background:#ea580c;color:#fff;padding:10px 18px;border-radius:6px;text-decoration:none;display:inline-block;">Write a Review →</a></p>
    <h2 style="color:#9a3412;">Need Help?</h2>
    <p>Our AI assistant Joy is available 24/7 to answer any questions about your order, product usage, or returns. Just open the chat bubble in your dashboard.</p>
    <hr style="margin:24px 0;border:none;border-top:1px solid #fed7aa;" />
    <p style="font-size:12px;color:#6b7280;">Dayjoy Wellness Pvt. Ltd. · support@dayjoy.in</p>
  </div>
</body></html>`;
return [{ json: { skip: false, html, subject: `How is your Dayjoy order working out?`, recipientEmail: r.customer?.email, orderId: r.id, orderNumber: r.orderNumber, tenantId: r.tenantId, reviewUrl } }];

